using System;

class Program
{
    static bool Check(string who)
    {
        // Filters run during pass one, before any finally block
        Console.WriteLine("  filter evaluated (" + who + ")");
        return true;
    }

    static void Inner()
    {
        try { throw new InvalidOperationException("boom"); }
        finally { Console.WriteLine("  inner finally runs (pass two)"); }
    }

    static void Middle()
    {
        try { Inner(); }
        catch (ArgumentException) { Console.WriteLine("  never: wrong type"); }
    }

    static void Main()
    {
        Console.WriteLine("Throwing InvalidOperationException:");
        try { Middle(); }
        catch (InvalidOperationException e) when (Check("outer"))
        {
            // Pass 1 found this handler; pass 2 ran inner finally first
            Console.WriteLine("  catch body runs last: " + e.Message);
        }
    }
}

using System;

// Custom exception: carries data a handler needs
class RateLimitException : Exception
{
    public int RetryAfterSeconds { get; private set; }

    public RateLimitException(string message, int retryAfter) : base(message)
    {
        RetryAfterSeconds = retryAfter;
    }

    public RateLimitException(string message, int retryAfter, Exception inner)
        : base(message, inner)
    {
        RetryAfterSeconds = retryAfter;
    }
}

class Program
{
    static void Call(int attempt)
    {
        if (attempt < 3) throw new RateLimitException("Too many requests", 2 * attempt);
        Console.WriteLine("attempt " + attempt + " succeeded");
    }

    static void Main()
    {
        for (int attempt = 1; attempt <= 3; attempt++)
        {
            try { Call(attempt); }
            catch (RateLimitException e)
            {
                // The handler reacts using the data on the exception
                Console.WriteLine("attempt " + attempt + " failed: " + e.Message
                    + ", retry after " + e.RetryAfterSeconds + "s");
            }
        }
    }
}

using System;

class Program
{
    [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    static void Fail() { throw new Exception("original"); }

    static void WithThrow()   { try { Fail(); } catch (Exception) { throw; } }
    static void WithThrowEx() { try { Fail(); } catch (Exception ex) { throw ex; } }
    static void Wrapped()
    {
        try { Fail(); }
        catch (Exception ex) { throw new InvalidOperationException("wrapped", ex); }
    }

    static void Show(string label, Action a)
    {
        try { a(); }
        catch (Exception e)
        {
            // Does the trace still mention Fail (where it really failed)?
            bool hasFail = e.StackTrace.Contains("Fail");
            Console.WriteLine(label + ": mentions Fail = " + hasFail
                + ", inner = " + (e.InnerException == null ? "none" : e.InnerException.Message));
        }
    }

    static void Main()
    {
        Show("throw;       ", WithThrow);
        Show("throw ex;    ", WithThrowEx);
        Show("throw new(ex)", Wrapped);
    }
}

using System;

class Program
{
    static bool Log(Exception e)
    {
        Console.WriteLine("  logged: " + e.Message);
        return false; // never handles, so nothing is unwound here
    }

    static void Work()
    {
        try { throw new InvalidOperationException("db down"); }
        finally { Console.WriteLine("  Work finally"); }
    }

    static void Main()
    {
        Console.WriteLine("Filter that logs and returns false:");
        try
        {
            try { Work(); }
            catch (Exception e) when (Log(e)) { Console.WriteLine("  not reached"); }
        }
        catch (InvalidOperationException)
        {
            Console.WriteLine("  outer handler got it");
        }
        // Order shows: logged first (stack intact), then Work finally, then outer catch
    }
}

using System;

class Res : IDisposable
{
    private string name;
    public Res(string name) { this.name = name; Console.WriteLine("open " + name); }
    public void Dispose() { Console.WriteLine("dispose " + name); }
}

class Program
{
    static void Main()
    {
        // using (...) expands to try/finally
        using (Res stream = new Res("stream"))
        using (Res writer = new Res("writer"))
        {
            Console.WriteLine("work with both");
        }
        Console.WriteLine("--- same thing written by hand ---");
        Res a = new Res("A");
        try
        {
            Res b = new Res("B");
            try { Console.WriteLine("work with both"); }
            finally { if (b != null) b.Dispose(); }
        }
        finally { if (a != null) a.Dispose(); }
        // Reverse order of acquisition: last opened, first disposed
    }
}

using System;

class Holder : IDisposable
{
    private bool disposed;

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this); // finalizer no longer needed
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposed) return; // idempotent
        if (disposing)
            Console.WriteLine("  releasing managed fields");
        Console.WriteLine("  releasing native handle");
        disposed = true;
    }

    ~Holder()
    {
        Console.WriteLine("  finalizer ran");
        Dispose(false); // never touch other managed objects here
    }
}

class Program
{
    static void Main()
    {
        Holder h = new Holder();
        Console.WriteLine("first Dispose:");
        h.Dispose();
        Console.WriteLine("second Dispose (no-op):");
        h.Dispose();
    }
}

using System;

class Program
{
    // Even with nullable annotations in a real project, the runtime does not
    // enforce them. A public API must validate its own arguments.
    static int Length(string s)
    {
        if (s == null) throw new ArgumentNullException("s");
        return s.Length;
    }

    static int Unsafe(string s)
    {
        return s.Length; // compiler cannot stop a caller passing null at runtime
    }

    static void Main()
    {
        string ok = "hello";
        string bad = null;
        Console.WriteLine("Length(\"hello\") = " + Length(ok));
        try { Length(bad); }
        catch (ArgumentNullException e) { Console.WriteLine("checked API: " + e.GetType().Name); }
        try { Unsafe(bad); }
        catch (NullReferenceException e) { Console.WriteLine("unchecked API: " + e.GetType().Name); }
    }
}

using System;
using System.Collections.Generic;

class Program
{
    // Models "T?" on an unconstrained T: returns default(T) when not found
    static T FindOrDefault<T>(List<T> items, Predicate<T> match)
    {
        foreach (T x in items) if (match(x)) return x;
        return default(T);
    }

    // With where T : struct we can return a real Nullable<T>
    static T? FindStruct<T>(List<T> items, Predicate<T> match) where T : struct
    {
        foreach (T x in items) if (match(x)) return x;
        return null;
    }

    static void Main()
    {
        List<int> nums = new List<int> { 0, 5, 9 };
        List<string> words = new List<string> { "a", "bb" };

        int found0 = FindOrDefault(nums, n => n == 0);
        int missing = FindOrDefault(nums, n => n == 7);
        Console.WriteLine("int found 0 -> " + found0 + ", missing -> " + missing + " (same!)");

        string w = FindOrDefault(words, s => s.Length == 9);
        Console.WriteLine("string missing -> " + (w == null ? "null" : w));

        int? r = FindStruct(nums, n => n == 7);
        Console.WriteLine("struct-constrained missing -> " + (r.HasValue ? "value" : "null"));
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static int FindSentinel(int[] a, int x)
    {
        for (int i = 0; i < a.Length; i++) if (a[i] == x) return i;
        return -1; // caller must remember to check
    }

    static int? FindNullable(int[] a, int x)
    {
        for (int i = 0; i < a.Length; i++) if (a[i] == x) return i;
        return null;
    }

    static bool TryFind(int[] a, int x, out int index)
    {
        for (int i = 0; i < a.Length; i++) if (a[i] == x) { index = i; return true; }
        index = 0;
        return false;
    }

    static void Main()
    {
        int[] data = { 4, 8, 15, 16 };
        Console.WriteLine("data = 4 8 15 16, looking for 99");
        Console.WriteLine("sentinel: " + FindSentinel(data, 99));
        int? n = FindNullable(data, 99);
        Console.WriteLine("nullable: " + (n ?? -1) + " (HasValue=" + n.HasValue + ")");
        int idx;
        if (TryFind(data, 15, out idx)) Console.WriteLine("Try: found 15 at " + idx);
        if (!TryFind(data, 99, out idx)) Console.WriteLine("Try: 99 not found");
    }
}

using System;

class Program
{
    // Statement form: sections, break/return, goto case, when guards
    static string Classify(int n)
    {
        switch (n)
        {
            case 0: return "zero";
            case 1:
                Console.Write("(1 falls to 2 via goto) ");
                goto case 2;
            case 2: return "small";
            default: return n < 0 ? "negative" : "big"; // C# 7 mcs has no 'when' in case
        }
    }

    // Expression-style equivalent in C# 7: a method that returns the value
    // (C# 8 would write:  n switch { 0 => "zero", < 0 => "negative", _ => "other" })
    static string Short(int n)
    {
        if (n == 0) return "zero";
        if (n < 0) return "negative";
        return "other";
    }

    static void Main()
    {
        int[] inputs = { 0, 1, 2, -5, 50 };
        foreach (int n in inputs)
            Console.WriteLine(n + " -> " + Classify(n) + " | short: " + Short(n));
    }
}

using System;

class Circle { public double R = 2; }
class Square { public double Side = 3; }

class Program
{
    // Same idea as a pattern switch, written with is/as (works on older compilers)
    static string Describe(object o)
    {
        if (o == null) return "null pattern";
        if (o is int)
        {
            int n = (int)o;
            if (n == 0) return "constant pattern 0";
            if (n > 100) return "type pattern + guard: big int " + n;
            return "type pattern: int " + n;
        }
        string s = o as string;
        if (s != null) return s.Length == 0 ? "empty string" : "string of length " + s.Length;
        Circle c = o as Circle;
        if (c != null) return "circle r=" + c.R;
        if (o is Square) return "square (type only, no variable)";
        return "something else";
    }

    static void Main()
    {
        object[] items = { null, 0, 7, 500, "", "hello", new Circle(), new Square(), 3.5 };
        foreach (object o in items) Console.WriteLine(Describe(o));
        // C# 8+ would write: o switch { null => ..., 0 => ..., int n when n > 100 => ..., _ => ... }
    }
}

using System;

// Closed set of "records": operations live in functions with a type switch
abstract class Shape { }
class Circle : Shape { public double R; public Circle(double r) { R = r; } }
class Rect : Shape { public double W, H; public Rect(double w, double h) { W = w; H = h; } }

class Program
{
    // Adding a new operation = one new function; adding a type = edit every switch
    static double Area(Shape s)
    {
        Circle c = s as Circle;
        if (c != null) return 3.14 * c.R * c.R;
        Rect r = s as Rect;
        if (r != null) return r.W * r.H;
        throw new ArgumentException("unknown shape"); // catches missing cases
    }

    static string Name(Shape s)
    {
        if (s is Circle) return "circle";
        if (s is Rect) return "rect";
        throw new ArgumentException("unknown shape");
    }

    static void Main()
    {
        Shape[] shapes = { new Circle(1), new Rect(2, 3) };
        foreach (Shape s in shapes)
            Console.WriteLine(Name(s) + " area = " + Area(s));
    }
}

using System;

class Program
{
    static void Parse(string s) { int.Parse(s); }

    static void Service(string s)
    {
        try { Parse(s); }
        catch (FormatException) // narrow: we know how to handle this one
        {
            Console.WriteLine("  service: bad number '" + s + "', using default 0");
        }
    }

    static void Boundary(string label, Action work)
    {
        try { work(); Console.WriteLine(label + ": ok"); }
        catch (Exception e) // broad catch only here: log once, keep process alive
        {
            Console.WriteLine(label + ": logged " + e.GetType().Name + ", returning error response");
        }
    }

    static void Main()
    {
        Boundary("request 1", () => Service("12"));
        Boundary("request 2", () => Service("abc"));      // handled inside
        Boundary("request 3", () => { string x = null; Console.WriteLine(x.Length); }); // bug surfaces
    }
}

using System;
using System.Diagnostics;

class Program
{
    static int ParseThrow(string s)
    {
        try { return int.Parse(s); }
        catch (FormatException) { return -1; }
    }

    static int ParseTry(string s)
    {
        int v;
        return int.TryParse(s, out v) ? v : -1;
    }

    static void Main()
    {
        int n = 20000;
        string bad = "not a number";
        long sink = 0;

        Stopwatch sw = Stopwatch.StartNew();
        for (int i = 0; i < n; i++) sink += ParseThrow(bad);
        long throwTicks = sw.ElapsedTicks;

        sw.Restart();
        for (int i = 0; i < n; i++) sink += ParseTry(bad);
        long tryTicks = sw.ElapsedTicks;

        Console.WriteLine(n + " failed parses each, result sum " + sink);
        Console.WriteLine("exception path slower than TryParse: " + (throwTicks > tryTicks));
        Console.WriteLine("at least 10x slower: " + (throwTicks > 10 * tryTicks));
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static int F()
    {
        int x = 1;
        try { return x; }       // value 1 is stored here
        finally { x = 2; }      // changing x afterwards does not change it
    }

    static List<int> G()
    {
        List<int> list = new List<int> { 1 };
        try { return list; }    // the reference is stored
        finally { list.Add(2); } // mutation through the reference IS visible
    }

    static List<int> H()
    {
        List<int> list = new List<int> { 1 };
        try { return list; }
        finally { list = new List<int> { 99 }; } // reassigning is NOT visible
    }

    static void Main()
    {
        Console.WriteLine("F() = " + F());
        Console.WriteLine("G() = " + string.Join(",", G()));
        Console.WriteLine("H() = " + string.Join(",", H()));
    }
}
